	}
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return enh004ProbeIndex{}, err
	}
	defer tx.Rollback()
	if _, err = tx.ExecContext(ctx, `CREATE TABLE meta(revision TEXT PRIMARY KEY,digest TEXT NOT NULL,documents INTEGER NOT NULL); CREATE TABLE docs(position INTEGER PRIMARY KEY,length INTEGER NOT NULL,locus TEXT NOT NULL); CREATE TABLE postings(term TEXT NOT NULL,position INTEGER NOT NULL,frequency INTEGER NOT NULL,PRIMARY KEY(term,position)) WITHOUT ROWID;`); err != nil {
		return enh004ProbeIndex{}, err
	}
