func PrepareCorpusStaging(brainDir string) (string, func(), error) {
	tempDir, err := os.MkdirTemp("", "entire-brain-pattern-corpus-")
	if err != nil {
		return "", nil, fmt.Errorf("create private pattern corpus staging directory: %w", err)
