	err := cmd.Run()
	elapsed := time.Since(start)
	stem := fmt.Sprintf("%05d-%s-%s-%s", len(r.rows), f.Name, binary.Label, phase)
	stdoutPath, stderrPath := filepath.Join(r.config.OutputDir, stem+".stdout.json"), filepath.Join(r.config.OutputDir, stem+".stderr.txt")
	for path, data := range map[string][]byte{stdoutPath: stdout.Bytes(), stderrPath: stderr.Bytes()} {
		if writeErr := os.WriteFile(path, data, 0o600); writeErr != nil {
			r.t.Fatal(writeErr)
		}
	}
	if err != nil {
		r.t.Fatalf("%s: %v; retained stdout/stderr: %s", stem, err, stderrPath)
	}
	var result map[string]json.RawMessage
	if err := json.Unmarshal(stdout.Bytes(), &result); err != nil {
		r.t.Fatalf("invalid CLI JSON: %v", err)
	}
	// A successful process may still report a workspace-member error.
	var envelope struct { Results []struct { Error string `json:"error"` } `json:"results"` }
	if err := json.Unmarshal(stdout.Bytes(), &envelope); err != nil || len(envelope.Results) != 1 || envelope.Results[0].Error != "" {
		r.t.Fatalf("unexpected workspace member result in %s: %s", stdoutPath, stdout.String())
	}
	rss, err := factProcessPeakRSS(runtime.GOOS, stderr.String())
	if err != nil {
		r.t.Fatal(err)
	}
	digest := sha256.Sum256(stdout.Bytes())
	hash := hex.EncodeToString(digest[:])
	refPhase := "original"
	if phase == "source_changed" || phase == "changed_record_visible" || phase == "corruption_recovery" {
		refPhase = "changed"
	}
	refKey := f.Name + "/" + refPhase + "/" + f.Queries[queryIndex]
	if ref, ok := r.refs[refKey]; ok && ref != hash {
		r.t.Fatalf("output mismatch %s binary=%s: want %s got %s (%s)", refKey, binary.Label, ref, hash, stdoutPath)
	}
	r.refs[refKey] = hash
	after := r.cacheInventory(root)
	var cacheBytes int64
	for _, file := range after {
		cacheBytes += file.Bytes
	}
	beforeJSON, _ := json.Marshal(before)
	afterJSON, _ := json.Marshal(after)
	r.record(factProcessMeasurement{Fixture: f.Name, Binary: binary.Label, Phase: phase, Sample: sample, Query: f.Queries[queryIndex],
		WallMS: float64(elapsed)/float64(time.Millisecond), PeakRSSBytes: rss, StdoutSHA256: hash, CacheBytes: cacheBytes,
		CacheStable: len(before) > 0 && bytes.Equal(beforeJSON, afterJSON), CacheFiles: after,
		Command: append([]string{"/usr/bin/time"}, args...), StdoutFile: stdoutPath, StderrFile: stderrPath})
}

func factProcessEnvironment(root string) []string {
	env := make([]string, 0)
	for _, entry := range os.Environ() {
		key, _, _ := strings.Cut(entry, "=")
		if strings.HasPrefix(key, "GIT_") || strings.HasPrefix(key, "ENTIRE_") || strings.HasPrefix(key, "XDG_") ||
			key == "HOME" || key == "TMPDIR" || key == "TMP" || key == "TEMP" || key == "FORCE_COLOR" {
			continue
		}
		env = append(env, entry)
	}
	values := map[string]string{"HOME": filepath.Join(root, "home"), "TMPDIR": filepath.Join(root, "tmp"),
		"TMP": filepath.Join(root, "tmp"), "TEMP": filepath.Join(root, "tmp"), "GIT_CONFIG_NOSYSTEM": "1", "GIT_CONFIG_GLOBAL": os.DevNull,
		"ENTIRE_CONFIG_DIR": filepath.Join(root, "entire-config"), "ENTIRE_TOKEN_STORE": "file", "ENTIRE_TOKEN_STORE_PATH": filepath.Join(root, "token.json"),
		"ENTIRE_TEST_AUTH_STORE_FILE": filepath.Join(root, "auth.json"), "ENTIRE_BRAIN_NO_EGRESS": "1", "ENTIRE_BRAIN_NO_GLOBAL_FACTS": "1", "NO_COLOR": "1"}
	for _, kind := range []string{"config", "data", "state", "cache"} {
		values["ENTIRE_PLUGIN_"+strings.ToUpper(kind)+"_DIR"] = filepath.Join(root, kind)
		xdg := "XDG_"+strings.ToUpper(kind)+"_HOME"
		values[xdg] = filepath.Join(root, kind)
	}
	keys := make([]string, 0, len(values))
	for key := range values {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	for _, key := range keys {
		env = append(env, key+"="+values[key])
	}
	return env
}

func (r *factProcessRunner) cacheInventory(root string) []factProcessCacheFile {
	r.t.Helper()
	var files []factProcessCacheFile
	cache := filepath.Join(root, "cache")
	err := filepath.WalkDir(cache, func(path string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.Type()&os.ModeSymlink != 0 {
			return fmt.Errorf("unexpected cache symlink: %s", path)
		}
		if entry.IsDir() {
			return nil
		}
		info, err := entry.Info()
		if err != nil {
			return err
		}
		hash, err := factProcessFileHash(path)
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(cache, path)
		if err != nil {
			return err
		}
		files = append(files, factProcessCacheFile{Path: filepath.ToSlash(rel), Bytes: info.Size(), Modified: info.ModTime().UnixNano(), SHA256: hash})
		return nil
	})
	if err != nil {
		r.t.Fatal(err)
	}
	return files
}

func (r *factProcessRunner) corruptCache(f factProcessFixture, binaryIndex int) {
	r.t.Helper()
	for _, file := range r.cacheInventory(f.Roots[binaryIndex]) {
		if !strings.HasSuffix(file.Path, ".sqlite") && !strings.HasSuffix(file.Path, ".db") {
			continue
		}
		path := filepath.Join(f.Roots[binaryIndex], "cache", filepath.FromSlash(file.Path))
		if err := os.WriteFile(path, []byte("deliberately corrupt disposable benchmark cache\n"), 0o600); err != nil {
			r.t.Fatal(err)
		}
	}
}

func (r *factProcessRunner) record(row factProcessMeasurement) {
	r.t.Helper()
	if err := r.log.Encode(row); err != nil {
		r.t.Fatal(err)
	}
	r.rows = append(r.rows, row)
}

func factProcessPeakRSS(platform, stderr string) (int64, error) {
	pattern, multiplier := `(\d+)\s+maximum resident set size`, int64(1)
	if platform == "linux" {
		pattern, multiplier = `Maximum resident set size \(kbytes\):\s*(\d+)`, 1024
	} else if platform != "darwin" {
		return 0, fmt.Errorf("unsupported RSS platform %q", platform)
	}
	match := regexp.MustCompile(pattern).FindStringSubmatch(stderr)
	if len(match) != 2 {
		return 0, fmt.Errorf("missing /usr/bin/time peak RSS for %s", platform)
	}
	value, err := strconv.ParseInt(match[1], 10, 64)
	if err != nil || value <= 0 || value > math.MaxInt64/multiplier {
		return 0, fmt.Errorf("invalid peak RSS %q", match[1])
	}
	return value * multiplier, nil
}

func factProcessFileHash(path string) (string, error) {
	file, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer file.Close()
	hash := sha256.New()
	if _, err := io.Copy(hash, file); err != nil {
		return "", err
	}
	return hex.EncodeToString(hash.Sum(nil)), nil
}

func factProcessWriteJSON(t *testing.T, path string, value any) {
	t.Helper()
	data, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, append(data, '\n'), 0o600); err != nil {
		t.Fatal(err)
	}
}

func factProcessSummarize(rows []factProcessMeasurement) map[string]any {
	groups := make(map[string][]factProcessMeasurement)
	for _, row := range rows {
		key := row.Fixture+"/"+row.Binary+"/"+row.Phase+"/"+row.Query
		groups[key] = append(groups[key], row)
	}
	result := make(map[string]any)
	for key, group := range groups {
		walls := make([]float64, 0, len(group))
		var peakRSS, maxCache int64
		for _, row := range group {
			walls = append(walls, row.WallMS)
			peakRSS, maxCache = max(peakRSS, row.PeakRSSBytes), max(maxCache, row.CacheBytes)
		}
		sort.Float64s(walls)
		median := walls[len(walls)/2]
		if len(walls)%2 == 0 {
			median = (median+walls[len(walls)/2-1])/2
		}
		result[key] = map[string]any{"samples": len(walls), "median_wall_ms": median, "min_wall_ms": walls[0],
			"max_wall_ms": walls[len(walls)-1], "max_peak_rss_bytes": peakRSS, "max_cache_bytes": maxCache}
	}
	return result
}

func TestFactProcessPeakRSS(t *testing.T) {
	t.Parallel()
	for _, test := range []struct { name, platform, text string; want int64; valid bool }{
		{"darwin", "darwin", "        32505856  maximum resident set size\n", 32505856, true},
		{"linux", "linux", "Maximum resident set size (kbytes): 31744\n", 32505856, true},
		{"missing", "darwin", "elapsed 0.5", 0, false},
		{"zero", "darwin", "0 maximum resident set size", 0, false},
		{"overflow", "linux", "Maximum resident set size (kbytes): 9223372036854775807", 0, false},
	} {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()
			got, err := factProcessPeakRSS(test.platform, test.text)
			if (err == nil) != test.valid || got != test.want {
				t.Fatalf("peak RSS=%d error=%v; want %d valid=%t", got, err, test.want, test.valid)
			}
		})
	}
}

func TestFactProcessSyntheticFixture(t *testing.T) {
	t.Parallel()
	records := factProcessSynthetic(10)
	seen := make(map[string]bool)
	for _, record := range records {
		if seen[record.ID] || record.Status != factmerge.StatusActive || record.Text == "" {
			t.Fatalf("invalid distinct synthetic record: %+v", record)
		}
		seen[record.ID] = true
	}
	if len(records) != 10 || records[0].Text == records[1].Text {
		t.Fatal("synthetic fixture must retain distinct component text")
	}
}

