func currentFactIndexRevision() factIndexRevision {
	return factIndexRevision{factIndexSchemaVersion, factIndexTokenizerVersion, factIndexLocusVersion, factIndexScorerVersion}
}

func factIndexRecordSignature(record factRecord) (string, error) {
	data, err := factIndexRecordBytes(record)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:]), nil
}

func factIndexRecordBytes(record factRecord) ([]byte, error) {
	if len(record.Text) > factIndexMaxRecordBytes {
		return nil, errFactIndexBudget
	}
	data, err := json.Marshal(record)
	if err != nil {
		return nil, fmt.Errorf("encode fact index record: %w", err)
	}
	if len(data) > factIndexMaxRecordBytes {
		return nil, errFactIndexBudget
	}
	return data, nil
}

func factIndexSourceRevision(ctx context.Context, scope string, source []factRecord) (string, []string, error) {
	if len(source) > factIndexMaxDocuments {
		return "", nil, errFactIndexBudget
	}
	h := sha256.New()
	header := struct {
		Revision   factIndexRevision
		Scope      string
		Projection string
	}{currentFactIndexRevision(), scope, "factstore-effective-record-v3"}
	if err := json.NewEncoder(h).Encode(header); err != nil {
		return "", nil, fmt.Errorf("encode fact index revision: %w", err)
	}
	signatures := make([]string, len(source))
	var sourceBytes int64
	for i := range source {
		if err := ctx.Err(); err != nil {
			return "", nil, err
		}
		data, err := factIndexRecordBytes(source[i])
		if err != nil {
			return "", nil, fmt.Errorf("encode fact index source: %w", err)
		}
		sourceBytes += int64(len(data))
		if sourceBytes > factIndexMaxSourceBytes {
			return "", nil, errFactIndexBudget
		}
		sum := sha256.Sum256(data)
		signatures[i] = hex.EncodeToString(sum[:])
		_, _ = h.Write(data)
		_, _ = h.Write([]byte{'\n'})
	}
	return hex.EncodeToString(h.Sum(nil)), signatures, nil
}

func factIndexDirectory(env base.EntireEnv, scope string) (string, error) {
	if strings.TrimSpace(scope) == "" || len(scope) > 4096 {
		return "", fmt.Errorf("fact index requires a source identity")
	}
	dirs, err := base.ResolvePluginDirs(env)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256([]byte(scope))
	return filepath.Join(dirs.Cache, factIndexNamespace, hex.EncodeToString(sum[:])), nil
}

// The cache root is resolved by PluginDirs, not derived from an artifact path.
// All descendants are pinned and refuse links before any reads or mutations.
type factIndexPinnedDirectory struct {
	cachePath     string
	cache         *os.Root
	cacheInfo     os.FileInfo
	namespace     *os.Root
	namespaceInfo os.FileInfo
	scope         *os.Root
	scopeInfo     os.FileInfo
	scopeName     string
}

func factIndexOpenDirectoryPath(path string) (*os.Root, os.FileInfo, error) {
	if err != nil {
		return nil, nil, err
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular() {
		return nil, nil, fmt.Errorf("%w: cache leaf is not a regular file", errFactIndexUnsafe)
	}
	f, err := root.OpenFile(name, os.O_RDONLY|base.FileLockOpenFlags()|base.MemoryStateReadOpenFlags(), 0)
	if err != nil {
		return nil, nil, err
	}
	opened, err := f.Stat()
	current, currentErr := root.Lstat(name)
	if err != nil || currentErr != nil || current.Mode()&os.ModeSymlink != 0 || !os.SameFile(info, opened) || !os.SameFile(info, current) {
		_ = f.Close()
		return nil, nil, fmt.Errorf("%w: cache leaf changed while opening", errFactIndexUnsafe)
	}
	if err = base.RejectOpenFileHardlink(name, f, opened, "fact index"); err != nil {
		_ = f.Close()
		return nil, nil, fmt.Errorf("%w: %w", errFactIndexUnsafe, err)
	}
	return f, info, nil
}

func factIndexLeafUnchanged(root *os.Root, name string, f *os.File, info os.FileInfo) error {
	opened, err := f.Stat()
	current, currentErr := root.Lstat(name)
	if err != nil || currentErr != nil || current.Mode()&os.ModeSymlink != 0 || !os.SameFile(info, opened) || !os.SameFile(info, current) || opened.Size() != info.Size() || current.Size() != info.Size() || !opened.ModTime().Equal(info.ModTime()) || !current.ModTime().Equal(info.ModTime()) {
		return fmt.Errorf("%w: cache leaf changed during reading", errFactIndexUnsafe)
	}
	if err := base.RejectOpenFileHardlink(name, f, opened, "fact index"); err != nil {
		return fmt.Errorf("%w: %w", errFactIndexUnsafe, err)
	}
	return nil
}

func readFactIndexDescriptor(ctx context.Context, p *factIndexPinnedDirectory, digest string) (factIndexDescriptor, error) {
	var descriptor factIndexDescriptor
	name := digest + ".json"
	f, info, err := factIndexOpenLeaf(p.scope, name, factIndexDescriptorMaxBytes)
	if err != nil {
		return descriptor, err
	}
	defer f.Close()
	data, err := io.ReadAll(io.LimitReader(&factIndexContextReader{ctx: ctx, reader: f}, factIndexDescriptorMaxBytes+1))
	if err != nil {
		return descriptor, err
	}
	if int64(len(data)) > factIndexDescriptorMaxBytes {
		return descriptor, errFactIndexBudget
	}
	if err = factIndexLeafUnchanged(p.scope, name, f, info); err != nil {
		return descriptor, err
	}
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()
	if err = decoder.Decode(&descriptor); err != nil {
		return descriptor, fmt.Errorf("decode fact index descriptor: %w", err)
	}
	var extra any
	if err = decoder.Decode(&extra); !errors.Is(err, io.EOF) {
		return descriptor, fmt.Errorf("invalid trailing fact index descriptor data")
	}
	if descriptor.Revision != currentFactIndexRevision() || descriptor.Source != digest || !factIndexHexDigest(descriptor.SHA256) || descriptor.Size < 1 || descriptor.Size > factIndexMaxBytes || descriptor.Documents < 0 || descriptor.Documents > factIndexMaxDocuments {
		return descriptor, fmt.Errorf("invalid fact index descriptor")
	}
	return descriptor, p.validate()
}

