func currentFactIndexRevision() factIndexRevision {
	return factIndexRevision{factIndexSchemaVersion, factIndexTokenizerVersion, factIndexLocusVersion, factIndexScorerVersion}
}

func factIndexRecordSignature(record factRecord) (string, error) {
	data, err := factIndexRecordBytes(record)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:]), nil
}

func factIndexRecordBytes(record factRecord) ([]byte, error) {
	if len(record.Text) > factIndexMaxRecordBytes {
		return nil, errFactIndexBudget
	}
	data, err := json.Marshal(record)
	if err != nil {
		return nil, fmt.Errorf("encode fact index record: %w", err)
	}
	if len(data) > factIndexMaxRecordBytes {
		return nil, errFactIndexBudget
	}
	return data, nil
}

func factIndexSourceRevision(ctx context.Context, scope string, source []factRecord) (string, []string, error) {
	if len(source) > factIndexMaxDocuments {
		return "", nil, errFactIndexBudget
	}
	h := sha256.New()
	header := struct {
		Revision   factIndexRevision
		Scope      string
		Projection string
	}{currentFactIndexRevision(), scope, "factstore-effective-record-v3"}
	if err := json.NewEncoder(h).Encode(header); err != nil {
		return "", nil, fmt.Errorf("encode fact index revision: %w", err)
	}
	signatures := make([]string, len(source))
	var sourceBytes int64
	for i := range source {
		if err := ctx.Err(); err != nil {
			return "", nil, err
		}
		data, err := factIndexRecordBytes(source[i])
		if err != nil {
			return "", nil, fmt.Errorf("encode fact index source: %w", err)
		}
		sourceBytes += int64(len(data))
		if sourceBytes > factIndexMaxSourceBytes {
			return "", nil, errFactIndexBudget
		}
		sum := sha256.Sum256(data)
		signatures[i] = hex.EncodeToString(sum[:])
		_, _ = h.Write(data)
		_, _ = h.Write([]byte{'\n'})
	}
	return hex.EncodeToString(h.Sum(nil)), signatures, nil
}

func factIndexDirectory(env base.EntireEnv, scope string) (string, error) {
	if strings.TrimSpace(scope) == "" || len(scope) > 4096 {
		return "", fmt.Errorf("fact index requires a source identity")
	}
	dirs, err := base.ResolvePluginDirs(env)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256([]byte(scope))
	return filepath.Join(dirs.Cache, factIndexNamespace, hex.EncodeToString(sum[:])), nil
}

