func factIndexOpenDirectoryPath(path string) (*os.Root, os.FileInfo, error) {
	if err != nil {
		return nil, nil, err
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular() {
		return nil, nil, fmt.Errorf("%w: cache leaf is not a regular file", errFactIndexUnsafe)
